const ahora = Date.now();
const margen = 120000;
const out = [];
$input.all().forEach(function (it) {
  const p = it.json;
  if (!p.id || !p.activo || !p.telegram_id) { return; }
  const min = Number(p.temp_intervalo) || 0;
  if (min <= 0) { return; }
  const ultima = Number(p.temp_ultima_comprobacion) || 0;
  if (ultima && (ahora - ultima) < (min * 60000 - margen)) { return; }
  out.push({ json: { id: p.id, nombre: p.nombre, telegram_id: String(p.telegram_id), temp_intervalo: min, temp_tipos: p.temp_tipos || 'Export,Import', temp_huella: p.temp_huella || '' } });
});
return out;

const ahora = Date.now();
const D = DateTime.now().setZone('Europe/Madrid');
const NL = String.fromCharCode(10);
const personas = $('Quién toca').all().map(function (i) { return i.json; });
const primero = $input.first();
const r = (primero && primero.json) ? primero.json : {};
const out = [];

function motivoDe(x) {
  const e = x.error;
  if (e && typeof e === 'object') { return String(e.message || e.description || JSON.stringify(e)); }
  return String(e || x.message || 'sin respuesta');
}
function esc(s) { return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function num(n) { if (n === null || n === undefined) { return '-'; } return String(Math.round(Number(n) * 10) / 10).replace('.', ','); }
function huella(txt) { let h = 2166136261; for (let i = 0; i < txt.length; i++) { h ^= txt.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h.toString(16) + '.' + txt.length; }
function sonda(n, cons, mn, mx, baja, alta) {
  let t = 'Sonda ' + n + ': consigna ' + num(cons) + ' °C · mín ' + num(mn) + ' · máx ' + num(mx);
  if (baja) { t += ' ⬇️ baja'; }
  if (alta) { t += ' ⬆️ alta'; }
  return t;
}
function bloque(f) {
  const l = [];
  const matriculas = [f.Tractora, f.Remolque].filter(Boolean).map(esc).join(' / ');
  l.push('⚠️ <b>' + esc(f.TipoPedido) + '</b> · ' + matriculas);
  const conductor = f.ConductorAlias || f.ConductorNombre;
  if (conductor) { l.push('👤 ' + esc(conductor) + (f.ConductorTelefonoEmpresa ? ' · 📞 ' + esc(f.ConductorTelefonoEmpresa) : '')); }
  l.push(esc(f.NombreCliente) + ' · pedido ' + esc(f.NumeroPedido) + (f.NumPedCliente ? ' (' + esc(f.NumPedCliente) + ')' : ''));
  l.push('Destino: ' + esc(f.Destino) + ' · fin ' + esc(String(f.FechaFin || '').slice(0, 5)));
  if (f.Temp1 !== null && f.Temp1 !== undefined) { l.push(sonda(1, f.Temp1, f.Temp1Min, f.Temp1Max, f.Temp1Baja, f.Temp1Alta)); }
  if (f.Temp2 !== null && f.Temp2 !== undefined) { l.push(sonda(2, f.Temp2, f.Temp2Min, f.Temp2Max, f.Temp2Baja, f.Temp2Alta)); }
  return l.join(NL);
}

if (!Array.isArray(r.temperaturas)) {
  if (D.minute < 15) { out.push({ json: { tipo: 'api_error', motivo: motivoDe(r).slice(0, 200) } }); }
  return out;
}

personas.forEach(function (p) {
  const tipos = String(p.temp_tipos || 'Export,Import').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
  const filas = r.temperaturas.filter(function (f) { return tipos.indexOf(f.TipoPedido) >= 0; });
  const base = { id: p.id, temp_intervalo: p.temp_intervalo, temp_ultima_comprobacion: ahora };
  if (!filas.length) { out.push({ json: Object.assign({ tipo: 'update', temp_huella: '' }, base) }); return; }
  const h = huella(JSON.stringify(filas));
  if (h === String(p.temp_huella || '')) { out.push({ json: Object.assign({ tipo: 'update', temp_huella: h }, base) }); return; }
  let cab = '🌡️ <b>Aviso temperaturas</b> · ' + D.toFormat('dd/MM HH:mm');
  if (r.actualizado === false) { cab += NL + '⚠️ <i>Lecturas de Movildata no actualizadas</i>'; }
  const partes = [];
  let actual = cab;
  filas.forEach(function (f) {
    const b = bloque(f);
    if ((actual + NL + NL + b).length > 3800) { partes.push(actual); actual = '(continúa)'; }
    actual += NL + NL + b;
  });
  partes.push(actual);
  partes.forEach(function (texto) {
    out.push({ json: { tipo: 'msg', persona_id: p.id, chat_id: p.telegram_id, text: texto, nueva_huella: h, temp_intervalo: p.temp_intervalo } });
  });
});
return out;

const ahora = Date.now();
const msgs = $('Preparar avisos').all().map(function (i) { return i.json; }).filter(function (j) { return j.tipo === 'msg'; });
const res = $input.all().map(function (i) { return i.json; });
const porPersona = {};
msgs.forEach(function (m, i) {
  const r = res[i] || {};
  let err = '';
  if (r.error) { err = (typeof r.error === 'object') ? String(r.error.message || r.error.description || JSON.stringify(r.error)) : String(r.error); }
  else if (!(r.ok === true || (r.result && r.result.message_id) || r.message_id)) { err = 'sin respuesta de Telegram'; }
  const e = porPersona[m.persona_id] || { m: m, errores: [] };
  if (err) { e.errores.push(err); }
  porPersona[m.persona_id] = e;
});
const out = [];
Object.keys(porPersona).forEach(function (k) {
  const e = porPersona[k];
  if (!e.errores.length) {
    out.push({ json: { id: e.m.persona_id, temp_intervalo: e.m.temp_intervalo, temp_ultima_comprobacion: ahora, temp_huella: e.m.nueva_huella } });
    return;
  }
  if (/blocked|Forbidden|chat not found|deactivated|kicked/i.test(e.errores.join(' '))) {
    out.push({ json: { id: e.m.persona_id, temp_intervalo: 0, temp_ultima_comprobacion: ahora, temp_huella: '' } });
  }
});
return out;

